// needsGitHub is false for every entiredb-sourced role: those fetch from a
// sibling cluster cert-only and never mint an installation token.
func (cfg subscriptionConfig) needsGitHub() bool {
	return cfg.kind != gitjobs.SourceKindEntireDB && cfg.kind != gitjobs.SourceKindEntireDBNamespace
}
func (cfg subscriptionConfig) acceptsKind(kind gitjobs.SourceKind) bool {
	return cfg.kind == "" || cfg.kind == kind
}
func (cfg subscriptionConfig) owns(parsed gitjobs.ParsedSubject) bool {
	return parsed.Placement.Jurisdiction == cfg.jurisdiction && parsed.Placement.ClusterID == cfg.clusterID && cfg.acceptsKind(parsed.SourceKind) && parsed.Op == gitjobs.OpSyncRepo && knownSourceKind(parsed.SourceKind)
}

// knownSourceKind gates owns() on the kinds this binary can actually sync, so
// a future kind on the wire is left for a worker that understands it.
func knownSourceKind(kind gitjobs.SourceKind) bool {
	switch kind {
	case gitjobs.SourceKindGithub, gitjobs.SourceKindEntireDB, gitjobs.SourceKindEntireDBNamespace:
		return true
	}
	return false
}

func (cfg subscriptionConfig) advisorySubjects() (string, string, string) {
	return strings.TrimSuffix(advisoryMaxDeliverySubject, ">") + cfg.durable,
		strings.TrimSuffix(advisoryTerminatedSubject, ">") + cfg.durable,
		advisoryQueueGroup + "-" + cfg.durable
)

type SourceKind string
type Op string

const (
	SourceKindGithub   SourceKind = "github"
	SourceKindEntireDB SourceKind = "entiredb"
	// SourceKindEntireDBNamespace is an entiredb sync scoped to the
	// Entire-owned refs/heads/entire/native/* namespace (COR-1566): same
	// body shape as entiredb, different replication scope on the worker,
	// and its own subject token so the two kinds land on separate durables.
	SourceKindEntireDBNamespace SourceKind = "entiredb_ns"

	OpSyncRepo Op = "sync_repo"

	GithubAppInstallationAuthRefPrefix = "github_app_installation:"
	return job, nil
}

// MsgID composes the JetStream dedup id for a job: source coordinates +
// target, per kind — github keys on the upstream owner/repo, entiredb on the
// source repo ULID. Shared by every publisher so retries and the duplicate
// window collapse identically no matter who published.
func MsgID(parsed ParsedSubject, job Job) string {
	if parsed.SourceKind == SourceKindEntireDB || parsed.SourceKind == SourceKindEntireDBNamespace {
		return fmt.Sprintf("%s/%s/%s/%s", parsed.Op, parsed.SourceKind, job.Source.SourceRepoULID(), job.Target.ULID)
	}
	return fmt.Sprintf("%s/%s/%s/%s/%s", parsed.Op, parsed.SourceKind, job.Source.Owner, job.Source.Repo, job.Target.ULID)
}

// EnsureStream is idempotent: create the stream if it's absent, otherwise
// reconcile any drift in the contract fields (including a Replicas scale-up
