	return parsed.Placement.Jurisdiction == cfg.jurisdiction && parsed.Placement.ClusterID == cfg.clusterID && cfg.acceptsKind(parsed.SourceKind) && parsed.Op == gitjobs.OpSyncRepo && knownSourceKind(parsed.SourceKind)
