              },
              {
                "text": " passes. I did not run ",
                "type": "text"
              },
              {
                "text": "mise run lint",
                "type": "text",
                "marks": [
                  {
                    "type": "code"
                  }
                ]
              },
              {
                "text": ".",
                "type": "text"
              }
            ]
          },
          {
            "type": "heading",
            "attrs": {
              "level": 2
            },
            "content": [
              {
                "text": "Follow-ups",
                "type": "text"
              }
            ]
          },
          {
            "type": "bulletList",
            "content": [
              {
                "type": "listItem",
                "content": [
                  {
                    "type": "paragraph",
                    "content": [
                      {
                        "text": "git-sync: authenticate the GitHub repo-size preflight and log its outcome. Without it, private repos over 1.5 GiB bootstrap as one pack.",
                        "type": "text"
                      }
                    ]
                  }
                ]
